package xyz.jovanstoiljkovic.isa.services;import org.springframework.data.repository.CrudRepository;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.stereotype.Service;import xyz.jovanstoiljkovic.isa.models.Admin;import java.util.Optional;@Servicepublic class AdminService extends BaseService<Admin>{    private BCryptPasswordEncoder encoder = new BCryptPasswordEncoder(12);    public AdminService(CrudRepository<Admin, Long> repo) {        super(repo);    }    @Override    public Optional<Admin> create(Admin item){        item.setPassword(encoder.encode(item.getPassword()));        repo.save(item);        return Optional.of(item);    }}